const lesson3PreviousPages={...pages};
function lesson3References(first=27,last=37){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson3/page-'+(first+i)+'.png" alt="Bài 3 · trang '+(first+i)+'"><figcaption>Trang '+(first+i)+'</figcaption></figure>').join('')+'</details>';}
function lesson3Home(){app.innerHTML=intro('HSK2 · LESSON 3',lesson3Data.title,lesson3Data.pinyin+' · '+lesson3Data.vi)+'<section class="hero"><div><h2>Xin phép & mượn đồ</h2><p>Hỏi số điện thoại, nhờ nói chậm và xin dùng đồ một lát.</p><a class="btn" href="#words">Học 21 mục từ →</a></div><div class="hero-mark" aria-hidden="true">借</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 21</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>27–37</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','可以、想 · Động từ + 一下'],['dialogue','Hội thoại','Ghi số điện thoại · Mượn máy tính và điện thoại'],['practice','Luyện tập','Điền từ · Đọc hiểu · Mô phỏng mượn đồ'],['listening','Luyện nghe','Bốn file Q2B3 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 3']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>如果你想借别人的手机，你怎么说？<br>你常常用手机做什么？</p><p class="sub">Bạn sẽ xin mượn điện thoại thế nào? Bạn thường dùng điện thoại làm gì?</p></article>'+lesson3References();}
function lesson3Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 3','Xin phép một cách tự nhiên.','Hai trọng tâm trong sách: 可以、想 và động từ đi với 一下.')+`<article class="card grammar"><h2>01 · 可以 và 想</h2><div class="pattern">Chủ ngữ + 可以 / 想 + động từ</div><p><b>可以</b>: có thể, được phép. <b>想</b>: muốn làm điều gì. Thường thêm 不 trước động từ năng nguyện để phủ định.</p>${grammarExamples([["我可以用一下你的手机吗？— 可以。","Wǒ kěyǐ yòng yíxià nǐ de shǒujī ma? — Kěyǐ.","Tôi dùng điện thoại của bạn một lát được không? — Được."],["上课可不可以打电话？— 不可以！","Shàng kè kě bu kěyǐ dǎ diànhuà? — Bù kěyǐ!","Trong giờ học có được gọi điện không? — Không được!"],["你想不想去？— 我不想去。","Nǐ xiǎng bu xiǎng qù? — Wǒ bù xiǎng qù.","Bạn có muốn đi không? — Tôi không muốn đi."]])}</article><article class="card grammar"><h2>02 · Động từ + 一下</h2><div class="pattern">Động từ + 一下 + tân ngữ</div><p>Diễn tả hành động diễn ra trong thời gian ngắn; thường làm lời đề nghị hoặc yêu cầu nhẹ nhàng hơn.</p>${grammarExamples([["我可以看一下你的书吗？","Wǒ kěyǐ kàn yíxià nǐ de shū ma?","Tôi xem sách của bạn một chút được không?"],["请等一下。","Qǐng děng yíxià.","Xin đợi một lát."],["我想用一下你的电脑。","Wǒ xiǎng yòng yíxià nǐ de diànnǎo.","Tôi muốn dùng máy tính của bạn một chút."]])}</article><article class="card grammar"><h2>Các mẫu hữu ích trong bài</h2>${grammarExamples([["我明天给你打电话。","Wǒ míngtiān gěi nǐ dǎ diànhuà.","Ngày mai tôi gọi điện cho bạn."],["请再说一遍。","Qǐng zài shuō yí biàn.","Xin nói lại một lần."],["请慢一点儿。","Qǐng màn yìdiǎnr.","Xin chậm một chút."],["可以，你用吧。 / 没问题，给。","Kěyǐ, nǐ yòng ba. / Méi wèntí, gěi.","Được, bạn dùng đi. / Không vấn đề gì, đây."],["对不起，我正在用。 / 没关系。","Duìbuqǐ, wǒ zhèngzài yòng. / Méi guānxi.","Xin lỗi, tôi đang dùng. / Không sao."]])}<p class="sub">电话、号 là các từ đi kèm 打电话、号码 trong bảng từ mới của sách.</p></article><a class="btn" href="#practice">Luyện mẫu câu →</a>`+lesson3References(29,30);}
function lesson3Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 3','Mượn đồ và ghi số điện thoại.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson3Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson3-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson3-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson3References(31,34);bindLesson2Voice(lesson3Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson3Dialogue();};document.querySelectorAll('[data-lesson3-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson3Line.split(',').map(Number);lesson2Speak(lesson3Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson3-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson3Data.dialogues[Number(b.dataset.lesson3Full)][1].map(l=>l[1]).join(' ')));}
let lesson3PracticeMode='vocab';
function gradeLesson3Exercise(mode,index,draft){const q=lesson3Data.exercises[mode][index],variants=[q[1]];if(mode==='reading'&&index===1)variants.push('给打电话');if(mode==='reading'&&index===2)variants.push('中国女朋友');if(mode==='reading'&&index===3)variants.push('很好');if(mode==='choose'&&index===3)variants.push('想');return {correct:variants.some(answer=>compareHanzi(draft,answer).correct),answer:q[1],note:q[2]};}
function lesson3Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 3','Xin phép, mượn đồ và hỏi số.','Luyện các bài tập trong sách và mô phỏng tình huống.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','要 · 想 · 可以'],['borrow','Mượn đồ'],['phone','Hỏi số điện thoại'],['summary','Tự tổng kết']].map(([id,label])=>'<button class="btn '+(lesson3PracticeMode===id?'':'secondary')+'" data-lesson3-mode="'+id+'">'+label+'</button>').join('')+'</div><div id="lesson3ExerciseArea"></div>';document.querySelectorAll('[data-lesson3-mode]').forEach(b=>b.onclick=()=>{lesson3PracticeMode=b.dataset.lesson3Mode;lesson3Practice();});renderLesson3ExerciseArea();}
function renderLesson3ExerciseArea(){const area=document.querySelector('#lesson3ExerciseArea'),mode=lesson3PracticeMode;if(mode==='borrow'){renderLesson3Borrow(area);return;}if(mode==='phone'){renderLesson3Phone(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu cần nhớ</h2><label for="lesson3SummaryWords">Từ ngữ</label><textarea id="lesson3SummaryWords" rows="4"></textarea><label for="lesson3SummaryPatterns">Mẫu câu</label><textarea id="lesson3SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu cùng tiến độ Lesson 3.</p></article>'+lesson3References(37,37);for(const[id,key]of [['lesson3SummaryWords','words'],['lesson3SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson3Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson3Summary=state.lesson3Summary||{};state.lesson3Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson3Exercises?.[mode]||{};area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson3Data.reading+'</p><p class="sub">Từ hỗ trợ trong đoạn: 女朋友 (bạn gái), 男朋友 (bạn trai), 妹妹 (em gái), 教 (dạy).</p></article>':'')+(mode==='choose'?'<p class="sub">Điền 要、想 hoặc 可以. Câu cuối chấp nhận cả 想 nếu phù hợp ý bạn muốn diễn đạt.</p>':'')+'<form id="lesson3ExerciseForm">'+lesson3Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson3Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson3Answer'+i+'" lang="zh-CN" value="'+esc(saved[i]?.draft||'')+'" placeholder="Gõ chữ Hán…"><div id="lesson3Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson3Result" role="status"></p></form>'+lesson3References(mode==='vocab'?28:36,mode==='vocab'?29:37);document.querySelector('#lesson3ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let correct=0;lesson3Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson3Answer'+i).value,r=gradeLesson3Exercise(mode,i,draft);records[i]={draft,correct:r.correct};correct+=r.correct?1:0;document.querySelector('#lesson3Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Câu trả lời tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson3Exercises=state.lesson3Exercises||{};state.lesson3Exercises[mode]=records;save();document.querySelector('#lesson3Result').textContent='Đúng '+correct+' / '+lesson3Data.exercises[mode].length+' câu.';};}
const lesson3BorrowTasks=[['看','书','xem sách'],['用','笔','dùng bút'],['借','电脑','mượn máy tính'],['借','手机','mượn điện thoại']];
function gradeLesson3Borrow(draft,verb,item){const text=normalizeHanzi(draft);return text.includes('可以')&&(text.includes('吗')||text.includes('可不可以'))&&text.includes('一下')&&text.includes(item)&&(text.includes(verb)||text.includes('借')||text.includes('用'));}
function renderLesson3Borrow(area){area.innerHTML='<p class="sub">Theo mẫu và tranh trang 30–31: hỏi mượn một lần bằng 可以…吗 và một lần bằng 可不可以…; luyện cả đồng ý lẫn từ chối có lý do.</p><div class="grid">'+lesson3BorrowTasks.map(([verb,item,vi],i)=>'<article class="card grammar"><h3>'+vi+' · '+verb+item+'</h3><label for="lesson3Borrow'+i+'">Viết câu xin phép có 一下</label><input class="lesson2-answer" id="lesson3Borrow'+i+'" lang="zh-CN"><button class="btn secondary" data-lesson3-borrow="'+i+'">Kiểm tra</button><p id="lesson3BorrowResult'+i+'" role="status"></p><details><summary>Hai cách hỏi và phản hồi gợi ý</summary><p>我可以'+verb+'一下你的'+item+'吗？<br>我可不可以'+verb+'一下你的'+item+'？<br>可以，给。<br>对不起，我正在用。<br>没关系！</p></details></article>').join('')+'</div>'+lesson3References(30,31);document.querySelectorAll('[data-lesson3-borrow]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson3Borrow),[verb,item]=lesson3BorrowTasks[i],draft=document.querySelector('#lesson3Borrow'+i).value;const correct=gradeLesson3Borrow(draft,verb,item);document.querySelector('#lesson3BorrowResult'+i).textContent=correct?'✓ Đúng mẫu xin phép.':'Gợi ý: 我可以'+verb+'一下你的'+item+'吗？';state.lesson3Exercises=state.lesson3Exercises||{};state.lesson3Exercises.borrow=state.lesson3Exercises.borrow||{};state.lesson3Exercises.borrow[i]={draft,correct};save();});for(let i=0;i<4;i++)document.querySelector('#lesson3Borrow'+i).value=state.lesson3Exercises?.borrow?.[i]?.draft||'';}
function renderLesson3Phone(area){area.innerHTML='<article class="card grammar"><h2>Phỏng vấn theo mẫu trang 35</h2><p>你的手机号是多少？<br>请慢一点儿。<br>请再说一遍。</p><p class="sub">Điền ba nhân vật và số giả định để luyện ghi số rồi tạo câu tường thuật.</p>'+[0,1,2].map(i=>'<label>Người '+(i+1)+'<input class="lesson2-answer" id="lesson3Person'+i+'" placeholder="Tên nhân vật"></label><label>Số điện thoại<input class="lesson2-answer" id="lesson3Phone'+i+'" inputmode="tel" placeholder="Số giả định"></label>').join('')+'<button class="btn" id="lesson3PhoneReport">Tạo câu tường thuật</button><p id="lesson3PhoneOutput" class="lesson2-reading" style="white-space:pre-line"></p></article>'+lesson3References(35,35);const saved=state.lesson3PhoneBook||{};for(let i=0;i<3;i++)for(const key of ['Person','Phone']){const el=document.querySelector('#lesson3'+key+i);el.value=saved[key+i]||'';el.oninput=()=>{state.lesson3PhoneBook=state.lesson3PhoneBook||{};state.lesson3PhoneBook[key+i]=el.value;save();};}document.querySelector('#lesson3PhoneReport').onclick=()=>{const s=state.lesson3PhoneBook||{};document.querySelector('#lesson3PhoneOutput').textContent=[0,1,2].filter(i=>s['Person'+i]&&s['Phone'+i]).map(i=>s['Person'+i]+'的手机号是'+s['Phone'+i]+'。').join('\n')||'Bạn điền tên và số giả định trước nhé.';};}
function lesson3BTNCMarkup(file){const group=lesson3BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B3; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson3BTNCReference();const id=lesson3BTNC.indexOf(group),saved=state.lesson3Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson3BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l3nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson3BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson3BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson3BTNCReference()+'</details>';}
function lesson3BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 3</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson3/btnc-answers-page14.png" alt="Đáp án BTNC bài 3, trang 14 của PDF"></details>';}
function bindLesson3BTNC(){lesson3BTNC.forEach((group,id)=>{document.querySelector('#lesson3BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l3nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson3BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson3Exercises=state.lesson3Exercises||{};state.lesson3Exercises['btnc'+id]=records;save();document.querySelector('#lesson3BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}
function lesson3Listening(){const groups=[{title:'03-1 · Ghi số điện thoại',d:0,tf:[['田中现在要给美京打电话。','Sai — 田中 nói ngày mai sẽ gọi.'],['田中不知道美京的电话号码。','Đúng — lúc đầu 田中 chưa có số.'],['美京没有笔。','Sai — 美京 đồng ý cho mượn bút.'],['美京知道田中的手机号。','Không được xác nhận — 田中 chưa cung cấp số của mình trong hội thoại.']],questions:[['田中明天想做什么？','给美京打电话。'],['美京的电话号码是多少？','136-1847-2834。'],['田中想借什么？','借美京的笔。'],['田中有没有给美京自己的电话号码？','没有。']]},{title:'03-2 · Mượn đồ',d:1,questions:[['海伦想借什么？','田中的电脑。'],['田中想借什么？','海伦的手机。'],['田中为什么不用他的手机？','因为他的手机没电了。'],['田中借手机做什么？','给黄老师打电话。']]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 3','Nghe và luyện theo tình huống.','Bốn file Q2B3 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">File Q2B3 thuộc bộ BTNC. Phần bản ghi và đáp án NC1–NC3 được đối chiếu theo PDF bài 3. Chưa xác định bản thu tương ứng mã 03-1, 03-2, 03-3 trong giáo trình.</div>'+['Q2B3.mp3','Q2B3.NC1.MP3','Q2B3.NC2.MP3','Q2B3.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson3-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson3BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson3-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Nhận định đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đối chiếu theo văn bản hội thoại, không phải đáp án từ audio BTNC.</p></article>').join('')+'<article class="card grammar"><h2>03-3 · Bài nghe mở rộng trong giáo trình</h2><p class="notice">Chưa có bản ghi lời nghe xác nhận cho mã 03-3 nên chưa chấm điểm phần này.</p><h3>Đúng / sai</h3><ol><li>文丽想学英语。</li><li>欧文想请文丽教他汉语。</li><li>欧文知道文丽的手机号。</li><li>文丽不知道欧文的手机号。</li></ol><h3>Chọn đáp án</h3><ol><li>文丽明年要……<br>A. 去美国工作　B. 去英国学习　C. 去美国学习</li><li>欧文的手机号码是……<br>A. 137-0219-6734　B. 137-0219-6434　C. 137-0217-6734</li><li>文丽的手机号码是……<br>A. 187-4327-5630　B. 189-4327-5636　C. 189-4327-5630</li></ol></article>'+lesson3References(31,36);bindLesson3BTNC();document.querySelectorAll('[data-lesson3-audio]').forEach(select=>select.onchange=()=>{document.querySelectorAll('audio')[Number(select.dataset.lesson3Audio)].playbackRate=Number(select.value);});document.querySelectorAll('audio').forEach(audio=>audio.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(other=>{if(other!==audio)other.pause();});});bindLesson2Voice(lesson3Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson3-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson3Data.dialogues[Number(b.dataset.lesson3Listen)][1].map(l=>l[1]).join(' ')));}
for(const[route,handler]of Object.entries({home:lesson3Home,grammar:lesson3Grammar,dialogue:lesson3Dialogue,practice:lesson3Practice,listening:lesson3Listening}))pages[route]=function(){if(state.lesson==='3')handler();else lesson3PreviousPages[route]();};
pages.writing=function(){lesson3PreviousPages.writing();if(state.lesson!=='3')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 3';const chars=[...new Set(lesson3Data.rows.map(r=>r[0]).join('').split(''))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
render();
